// Workflow D · Format offers (Task 3.5 contract — no date math, labels come from Django)
const body = $input.item.json.body || $input.item.json;

const patientName  = body.patient_name || 'Patient';
const patientPhone = body.patient_phone || '';
const serviceName  = body.service_name || 'Consultation';
const clinicName   = body.clinic_name || 'Clinic';
const requestId    = body.request_id || '';
const chatId       = body.telegram_chat_id || null;
const expiryMin    = body.expiry_minutes || 60;
const channels     = Array.isArray(body.dispatch_channels)
  ? body.dispatch_channels : ['whatsapp', 'sms', 'voice'];
const slots        = body.candidate_slots || [];

const numberEmojis = ['1️⃣', '2️⃣', '3️⃣', '4️⃣'];

// Options MUST stay in payload order — Workflow C resolves "2" against this order.
const options = slots.map((slot, idx) => ({
  number: idx + 1,
  emoji: numberEmojis[idx] || `${idx + 1}.`,
  slot_offer_id: slot.id,
  doctor_name: slot.doctor_name || 'Doctor',
  date_label: slot.date_label || '',
  time_label: slot.time_label || '',
  label: `${numberEmojis[idx] || (idx + 1) + '.'} ${slot.date_label} at ${slot.time_label} (${slot.doctor_name})`,
}));

const optionsText = options.map(o => `\n${o.emoji} ${o.date_label} at ${o.time_label} (${o.doctor_name})`).join('');

// ---- Reply grammar (Phase 3 / step 3.2) ------------------------------------
// The patient answers with an option NUMBER, so the sentence has to match how
// many options were actually sent:
//   1 -> "Reply 1"      2 -> "Reply 1 or 2"      3+ -> "Reply 1, 2, or 3"
// The old text hardcoded the first two numbers ("Reply 1, 2, or N"), which read
// "Reply 1, 2, or 1" for a single option and "Reply 1, 2, or 2" for two.
const countWord = (n, one, many) => `${n} ${Number(n) === 1 ? one : many}`;
const replyHint = options.length === 0
  ? ''
  : options.length === 1
    ? 'Reply 1'
    : options.length === 2
      ? 'Reply 1 or 2'
      : `Reply ${options.slice(0, -1).map(o => o.number).join(', ')}, or ${options.length}`;

// One option is a "slot is ready", not "slots are ready".
// Zero options never happens through the dashboard (the engine proposes at
// least one), but if it ever does the text must not claim options exist — the
// adapter's no_slots guard keeps this message from being sent at all.
const smsBody = options.length === 0
  ? `${clinicName}: We could not find a free ${serviceName} time for your request. Our front desk will call you shortly.`
  : `${clinicName}: Your ${serviceName} ${options.length === 1 ? 'slot is' : 'slots are'} ready.` +
    options.map(o => ` ${o.number}) ${o.date_label} ${o.time_label} (${o.doctor_name})`).join('') +
    ` ${replyHint} to lock in your time. Held for ${countWord(expiryMin, 'minute', 'minutes')}.`;

const messageText =
  `✨ <b>Available Appointment Times</b>\n\n` +
  `Hello <b>${patientName}</b>, our front desk has reviewed your request for <b>${serviceName}</b> and reserved the following options for you:\n` +
  `${optionsText}\n\n` +
  `⏳ <i>Please tap your preferred time below to confirm. These options are held for <b>${countWord(expiryMin, 'minute', 'minutes')}</b> so that all patients have fair access to the doctor's calendar.</i>`;

const inlineKeyboard = options.map(o => ([
  { text: o.label, callback_data: `select_slot_${o.slot_offer_id}` },
]));

return {
  json: {
    // Existing fields (Respond node + Telegram node keep working)
    channel: body.channel || 'web',
    chat_id: chatId,
    patient_name: patientName,
    request_id: requestId,
    message_text: messageText,
    inline_keyboard: inlineKeyboard,
    slots_count: options.length,
    // Task 3.5 additions for the channel legs
    clinic_name: clinicName,
    patient_phone: patientPhone,
    service_name: serviceName,
    expiry_minutes: expiryMin,
    offer_expires_at: body.offer_expires_at || '',
    options,
    options_text: optionsText,
    sms_body: smsBody,
    whatsapp_params: options.map(o => o.label),
    want_whatsapp: channels.includes('whatsapp'),
    want_sms: channels.includes('sms'),
    want_voice: channels.includes('voice'),
  },
};

// Workflow D · Provider Config & Adapter (single source of provider config)
// Reads deployment config from $env — no node hardcodes a URL, key or sender id.
// Emits ONE item per active channel (want_* + the chat_id rule), so no IF nodes are needed.
//
// Mock mode (PROVIDER_MOCK unset or true) does NOT skip the send nodes: it points every
// provider URL at the in-cluster Provider Simulator workflow (06_Provider_Simulator), so
// the real HTTP nodes, their bodies and the real failure path are exercised today.
// Flip-live = PROVIDER_MOCK=false + real VOICEBIP_* / WHATSAPP_* values.
const src = $input.all()[0].json;

const env = (name, fallback = '') => {
  try { const v = $env[name]; return (v === undefined || v === null) ? fallback : String(v); }
  catch (e) { return fallback; }
};
const truthy = (v) => ['1', 'true', 'yes', 'on'].includes(String(v).trim().toLowerCase());

const providerMock = env('PROVIDER_MOCK') === '' ? true : truthy(env('PROVIDER_MOCK'));
const providerMockFail = truthy(env('PROVIDER_MOCK_FAIL'));

// ---- WhatsApp message mode -------------------------------------------------
// Meta rejects business-initiated free-form text outside the 24-hour customer
// service window (error 131047), and a slot offer always goes to a patient who
// has not messaged us recently. So 'template' is the only correct live mode; the
// approved template must exist before the leg may fire.
const waMode = (env('WHATSAPP_TEMPLATE_MODE', 'template') || 'template').trim().toLowerCase() === 'text'
  ? 'text' : 'template';
// In mock mode a placeholder name is assumed so the template body is still
// exercised by the simulator. Live mode stays empty until the template exists.
const waTemplateName = providerMock
  ? env('WHATSAPP_TEMPLATE_NAME', 'mock_clinic_slot_offer')
  : env('WHATSAPP_TEMPLATE_NAME');
const waTemplateLang = env('WHATSAPP_TEMPLATE_LANG', 'en_US') || 'en_US';
const waParamOrder = env(
  'WHATSAPP_TEMPLATE_PARAM_ORDER',
  'patient_name,service_name,option_1,option_2,option_3,expiry'
).split(',').map((k) => k.trim()).filter(Boolean);
const waQuickReplies = env('WHATSAPP_TEMPLATE_QUICK_REPLIES', 'true') === ''
  ? true : truthy(env('WHATSAPP_TEMPLATE_QUICK_REPLIES', 'true'));

const cfg = {
  voicebipApiUrl: env('VOICEBIP_API_URL'),
  voicebipApiKey: env('VOICEBIP_API_KEY'),
  voiceAgentId: env('VOICEBIP_VOICE_AGENT_ID'),
  callerId: env('VOICEBIP_CALLER_ID'),
  smsSenderId: env('VOICEBIP_SMS_SENDER_ID', 'Cedarcare'),
  whatsappApiUrl: env('WHATSAPP_API_URL', 'https://graph.facebook.com/v19.0/'),
  whatsappPhoneId: env('WHATSAPP_PHONE_NUMBER_ID'),
  whatsappToken: env('WHATSAPP_ACCESS_TOKEN'),
  simulatorUrl: env('PROVIDER_SIMULATOR_URL', 'http://127.0.0.1:5678/webhook/provider-sim'),
};

const requestId = src.request_id || '';
const patientPhone = src.patient_phone || '';
const optionsCount = src.slots_count || (src.options ? src.options.length : 0);
const expiryMinutes = src.expiry_minutes || 60;

// Meta wants E.164 without the plus; Django re-normalizes whatever comes back.
const waTo = String(patientPhone).replace(new RegExp('[^0-9]', 'g'), '');

// Which channels should fire. The WhatsApp leg is the instant-message checkbox;
// a patient with a Telegram chat already got the Telegram card from Django itself.
const active = [];
if (src.want_whatsapp && !src.chat_id) active.push('whatsapp');
if (src.want_sms) active.push('sms');
if (src.want_voice) active.push('voice');

const configured = providerMock
  ? { whatsapp: true, sms: true, voice: true }
  : {
      sms: Boolean(cfg.voicebipApiUrl && cfg.voicebipApiKey),
      voice: Boolean(cfg.voicebipApiUrl && cfg.voicebipApiKey && cfg.voiceAgentId),
      whatsapp: Boolean(cfg.whatsappPhoneId && cfg.whatsappToken),
    };

// Voice quiet-hours gate (08:00–19:00 Africa/Lagos) — a gate, not date math for labels.
let voiceInWindow = true;
try {
  const lagosHour = Number(new Intl.DateTimeFormat('en-GB', { timeZone: 'Africa/Lagos', hour: 'numeric', hour12: false }).format(new Date()));
  voiceInWindow = lagosHour >= 8 && lagosHour < 19;
} catch (e) { voiceInWindow = true; }

// Dedupe guard (best-effort; static data is not persisted in manual test runs -
// Django's PATIENT_ALREADY_BOOKED + offer state remain authoritative).
// Phase 3 / step 3.4: reading the window and stamping it are two separate steps at last.
// A leg that is skipped never reached a provider, so it must not burn the window -
// otherwise the operator fixes the cause, re-dispatches minutes later, gets
// duplicate_dispatch (deliberately unlogged) and the patient silently receives nothing.
// The stamp is written below, after the route for each channel is known.
const seen = {};
let seenStore = null;
try {
  const sd = $getWorkflowStaticData('global');
  sd.seen = sd.seen || {};
  seenStore = sd.seen;
  const now = Date.now();
  for (const k of Object.keys(seenStore)) { if (now - seenStore[k] > 600000) delete seenStore[k]; }
  for (const ch of active) seen[ch] = Boolean(seenStore[requestId + ':' + ch]);
} catch (e) { /* static data unavailable */ }

// ---- WhatsApp template parameters ------------------------------------------
// The approved template's body placeholders are positional. Meta numbers them
// {{1}}… so the order in env must match the approved template exactly; the option
// labels are what the patient taps, so they must stay in payload order (Workflow C
// resolves "2" against that same order).
const optionLabels = (Array.isArray(src.whatsapp_params) && src.whatsapp_params.length)
  ? src.whatsapp_params
  : (src.options || []).map((o) => o.label);

const paramValue = (key) => {
  if (key === 'patient_name') return src.patient_name || 'Patient';
  if (key === 'service_name') return src.service_name || 'Consultation';
  if (key === 'clinic_name') return src.clinic_name || 'Clinic';
  if (key === 'expiry') return String(expiryMinutes);
  const m = /^option_([0-9]+)$/.exec(key);
  if (m) {
    const label = optionLabels[Number(m[1]) - 1];
    return label || '—';
  }
  return '—';
};

const buildWhatsAppBody = () => {
  if (waMode === 'text') {
    return {
      messaging_product: 'whatsapp',
      to: waTo,
      type: 'text',
      text: { body: src.sms_body || src.message_text || '' },
      biz_opaque_callback_data: requestId,
    };
  }
  const components = [{
    type: 'body',
    parameters: waParamOrder.map((k) => ({ type: 'text', text: paramValue(k) })),
  }];
  if (waQuickReplies) {
    // Meta allows at most three quick-reply buttons; the engine caps options to
    // three for WhatsApp even though Telegram can show more.
    optionLabels.slice(0, 3).forEach((label, idx) => {
      components.push({
        type: 'button',
        sub_type: 'quick_reply',
        index: String(idx),
        parameters: [{ type: 'payload', payload: String(idx + 1) }],
      });
    });
  }
  return {
    messaging_product: 'whatsapp',
    to: waTo,
    type: 'template',
    template: {
      name: waTemplateName,
      language: { code: waTemplateLang },
      components: components,
    },
    // Meta echoes this in every status callback, which is how a real wamid is
    // linked back to a BookingRequest (nothing else survives the round trip).
    biz_opaque_callback_data: requestId,
  };
};

const buildRequest = (channel) => {
  if (channel === 'whatsapp') {
    const headers = providerMock
      ? { Authorization: 'Bearer mock' }
      : { Authorization: 'Bearer ' + cfg.whatsappToken };
    const url = providerMock
      ? cfg.simulatorUrl + '/whatsapp'
      : cfg.whatsappApiUrl + cfg.whatsappPhoneId + '/messages';
    return { url, headers, body: buildWhatsAppBody() };
  }

  if (providerMock) {
    // Same request shape, different destination: the simulator answers in-cluster.
    const headers = { Authorization: 'Bearer mock' };
    const body = channel === 'sms'
      ? { to: patientPhone, message: src.sms_body || '', sender_id: cfg.smsSenderId,
          metadata: { request_code: requestId, channel } }
      : { to: patientPhone, agent_id: 'mock-agent', caller_id: 'mock-caller',
          metadata: { request_code: requestId, channel },
          variables: { patient_name: src.patient_name || 'Patient',
                       clinic_name: src.clinic_name || 'Clinic',
                       service_name: src.service_name || 'Consultation',
                       options_count: optionsCount, expiry_minutes: expiryMinutes } };
    return { url: cfg.simulatorUrl + '/' + channel, headers, body };
  }

  if (channel === 'sms') {
    return {
      url: cfg.voicebipApiUrl + '/sms',
      headers: { Authorization: 'Bearer ' + cfg.voicebipApiKey },
      body: { to: patientPhone, message: src.sms_body || '', sender_id: cfg.smsSenderId,
              metadata: { request_code: requestId, channel: 'sms' } },
    };
  }
  return {
    url: cfg.voicebipApiUrl + '/voice/calls',
    headers: { Authorization: 'Bearer ' + cfg.voicebipApiKey },
    body: { to: patientPhone, agent_id: cfg.voiceAgentId, caller_id: cfg.callerId,
            metadata: { request_code: requestId, channel: 'voice' },
            variables: { patient_name: src.patient_name || 'Patient',
                         clinic_name: src.clinic_name || 'Clinic',
                         service_name: src.service_name || 'Consultation',
                         options_count: optionsCount, expiry_minutes: expiryMinutes } },
  };
};

// Why a channel will not fire, most fundamental first: nothing to offer at all,
// a repeat (duplicate), a patient with no number (nothing can be sent), the
// voice quiet hours, a channel whose credentials are absent, and finally a
// configured WhatsApp leg with no approved template.
const skipReasonFor = (channel) => {
  // Phase 3 / step 3.2: with zero options there is nothing to say. Django falls
  // back to the availability engine when the receptionist approves no explicit
  // slots, and the engine can legitimately find none - so without this guard
  // every channel would text/call the patient with an empty option list
  // ("Reply 1, 2, or 0").
  if (optionsCount === 0) return 'no_slots';
  if (seen[channel]) return 'duplicate_dispatch';
  // Phase 2: every channel left needs a destination number — a phoneless
  // patient is reachable only through the Telegram card, which Django sends
  // itself and which never reaches this adapter.
  if (!patientPhone) return 'missing_phone';
  if (channel === 'voice' && !voiceInWindow) return 'outside_call_window';
  if (!configured[channel]) return 'provider_not_configured';
  if (channel === 'whatsapp' && waMode === 'template' && !waTemplateName) return 'whatsapp_template_not_configured';
  return null;
};

const out = active.map((channel) => {
  const skipReason = skipReasonFor(channel);
  const route = skipReason ? 'skip' : channel;
  // Never build a request for a channel that will not send: a skipped leg has no
  // URL, and nothing downstream can accidentally use one.
  const request = skipReason ? { url: '', headers: {}, body: null } : buildRequest(channel);

  return { json: {
    ...src,
    provider_channel: channel,
    provider_request: {
      route,
      skip_reason: skipReason,
      method: 'POST',
      ...request,
    },
    adapter_meta: {
      channel,
      provider_mock: providerMock,
      provider_mock_fail: providerMockFail,
      configured: configured[channel],
      voice_in_window: voiceInWindow,
      duplicate: Boolean(seen[channel]),
      request_id: requestId,
      whatsapp_mode: channel === 'whatsapp' ? waMode : null,
      whatsapp_template: channel === 'whatsapp' && waMode === 'template' ? waTemplateName : null,
      external_ref_hint: channel === 'whatsapp'
        ? ('wamid.mock-whatsapp-' + requestId)
        : ('mock-' + channel + '-' + requestId),
      missing_env: providerMock ? [] : Object.entries({
        VOICEBIP_API_URL: cfg.voicebipApiUrl,
        VOICEBIP_API_KEY: cfg.voicebipApiKey,
        VOICEBIP_VOICE_AGENT_ID: cfg.voiceAgentId,
        VOICEBIP_CALLER_ID: cfg.callerId,
        WHATSAPP_PHONE_NUMBER_ID: cfg.whatsappPhoneId,
        WHATSAPP_ACCESS_TOKEN: cfg.whatsappToken,
        WHATSAPP_TEMPLATE_NAME: waTemplateName,
        DJANGO_WEBHOOK_SECRET: env('DJANGO_WEBHOOK_SECRET'),
      }).filter(([, v]) => !v).map(([k]) => k),
    },
  } };
});

// Stamp the dedupe window only for the legs that will actually fire. One condition
// covers every skip reason (no_slots, missing_phone, outside_call_window,
// provider_not_configured, whatsapp_template_not_configured): a skip means no provider
// was contacted, so the window stays open for the retry that fixes it.
if (seenStore) {
  const stampedAt = Date.now();
  for (const item of out) {
    const channel = item.json.provider_channel;
    const request = item.json.provider_request;
    if (channel && request && request.skip_reason === null) {
      seenStore[requestId + ':' + channel] = stampedAt;
    }
  }
}

return out.length ? out : [{ json: { ...src, provider_channel: null, provider_request: { route: 'skip', skip_reason: 'no_active_channel', method: 'POST', url: '', headers: {}, body: null }, adapter_meta: { channel: null, provider_mock: providerMock, provider_mock_fail: providerMockFail, configured: false, voice_in_window: voiceInWindow, duplicate: false, request_id: requestId, whatsapp_mode: null, whatsapp_template: null, external_ref_hint: null, missing_env: [] } } }];

// Workflow D · Stage D-2 — reattach the voice payload after the 30s status probe.
// The probe response replaces the item, but the send/log nodes need the adapter payload,
// so pull the voice item back from the adapter and record why we did (or didn't) call.
const probe = $input.first().json || {};

const voiceItem = $('Provider Config & Adapter').all()
  .map(i => i.json)
  .find(j => j && j.provider_channel === 'voice');

const truthy = (v) => v === true || v === 'true' || v === 1 || v === '1';

// Fail safe, and the reason it has to be a flag rather than a synthetic skip payload:
// `IF Voice Still Needed` only looks at `should_skip`, which used to come from the probe
// alone. A missing adapter item therefore passed the gate and reached the send node with
// `provider_request.url === undefined` - the comment said "do NOT place a call", but the
// outcome was a node error that aborted the workflow, not a record.
const payloadMissing = !voiceItem;
const shouldSkip = truthy(probe.should_skip_voice_call) || payloadMissing;
const skipReason = payloadMissing ? 'voice_payload_missing' : 'patient_already_engaged';

const payload = voiceItem || {
  provider_channel: 'voice',
  // The probe still knows which request this is; the adapter is the thing that is gone.
  request_id: probe.request_id || '',
  provider_request: { route: 'skip', skip_reason: 'voice_payload_missing' },
};

return [{ json: {
  ...payload,
  provider_request: shouldSkip
    ? { ...(payload.provider_request || {}), route: 'skip', skip_reason: skipReason }
    : payload.provider_request,
  voice_guard: {
    checked: true,
    checked_at: new Date().toISOString(),
    wait_seconds: 30,
    should_skip: shouldSkip,
    request_status: probe.status || null,
    has_active_hold: truthy(probe.has_active_hold),
    has_confirmed_booking: truthy(probe.has_confirmed_booking),
    appointment_code: probe.appointment_code || null,
  },
} }];

// Workflow D · Stage D-3 — log the provider outcome to Django (authoritative record).
// Runs for BOTH the success and the error output of the send node: the dashboard's
// Needs Attention tab reads InteractionLog rows with status failed / no_answer.
const incoming = $input.first().json || {};
const base = $('Provider Config & Adapter').all()
  .map(i => i.json)
  .find(j => j && j.provider_channel === 'whatsapp') || {};

const isError = Boolean(incoming.error);
const resp = isError ? {} : incoming;

// >>> provider-error-classification (canonical copy — byte-identical in all three
// Log * Interaction nodes; test_lognodes.js asserts that) >>>
// n8n hands a failed HTTP call to this node as { message, name, stack } — plus a
// `code` for transport errors. There is NO error.status: the status only exists as
// the message prefix, and the response body is embedded as a JSON *string literal*:
//   404 - "{\"code\":404,\"message\":\"...\"}"
// So the status must be read from the prefix and the body needs a real two-step parse.
const STATUS_LABEL = {
  400: 'Provider rejected the request',
  401: 'Provider authentication failed',
  403: 'Provider refused access',
  404: 'Provider endpoint not found',
  409: 'Provider reported a conflict',
  422: 'Provider rejected the request',
  429: 'Provider rate limit reached',
};
const TRANSPORT_LABEL = {
  ECONNREFUSED: 'Provider endpoint refused the connection',
  ENOTFOUND: 'Provider host could not be resolved',
  ETIMEDOUT: 'Provider did not respond in time',
  ECONNABORTED: 'Provider did not respond in time',
  ECONNRESET: 'Provider closed the connection',
};

// Display-only clean-up: one line, no escape residue, no wrapping quotes.
const tidy = (value) => {
  if (typeof value === 'number') return String(value);
  if (typeof value !== 'string') return '';
  return value
    .replace(/\\[nrt]/g, ' ')
    .replace(/\\"/g, '"')
    .replace(/^["']|["']$/g, '')
    .replace(/\s+/g, ' ')
    .trim();
};

// Decode the embedded body: JSON string literal -> JSON payload. A hand-rolled
// .replace(/\\"/g, '"') is NOT equivalent: it corrupts nested escaped quotes and
// the parse then throws, which is how the raw wrapper used to reach reception.
const asObject = (body) => {
  let value = String(body == null ? '' : body).trim();
  for (let i = 0; i < 3; i += 1) {
    if (value[0] === '{') {
      try { return JSON.parse(value); } catch (e) { return null; }
    }
    if (value[0] !== '"') return null;
    const end = value.lastIndexOf('"');
    if (end <= 0) return null;
    try { value = JSON.parse(value.slice(0, end + 1)); } catch (e) { return null; }
  }
  return null;
};

const firstText = (list) => {
  if (!Array.isArray(list)) return '';
  for (const item of list) {
    const text = tidy(typeof item === 'string' ? item : (item && (item.message || item.detail || item.msg)));
    if (text) return text;
  }
  return '';
};

// The provider's own sentence, in the order providers actually use it.
const providerSentence = (body) => {
  const parsed = asObject(body);
  if (!parsed) return tidy(body);
  const err = parsed.error;
  const candidates = [
    parsed.detail, parsed.message, parsed.error_description, parsed.description, parsed.hint,
    typeof err === 'string' ? err : '',
    err && err.message, err && err.title,
    err && err.error_data && err.error_data.details,
    firstText(parsed.errors),
  ];
  for (const candidate of candidates) {
    const text = tidy(candidate);
    if (text) return text;
  }
  return tidy(body);
};

// -> { status: number|null, detail: string (<=300) } — one sentence reception can act on.
const classifyProviderError = (err) => {
  // Parse from the RAW message: tidy() unescapes quotes and must never run first,
  // or the JSON string literal stops being a valid literal.
  const message = (err && typeof err.message === 'string') ? err.message : '';
  const explicit = Number(err && (err.status || err.httpCode || err.statusCode));
  const prefixed = message.match(/^\s*(\d{3})\s*-\s*([\s\S]*)$/);
  const status = (Number.isFinite(explicit) && explicit >= 400) ? explicit
    : (prefixed ? Number(prefixed[1]) : null);
  if (status) {
    const label = STATUS_LABEL[status] || (status >= 500 ? 'Provider server error' : 'Provider returned an error');
    const sentence = providerSentence(prefixed ? prefixed[2] : '');
    return { status, detail: (label + (sentence ? ': ' + sentence : '')).slice(0, 300) };
  }
  const code = tidy(err && err.code).toUpperCase();
  if (TRANSPORT_LABEL[code]) return { status: null, detail: TRANSPORT_LABEL[code].slice(0, 300) };
  return { status: null, detail: (tidy(message) || tidy(err) || 'Provider call failed').slice(0, 300) };
};
// <<< provider-error-classification <<<

const providerStatus = String(resp.status || '').toLowerCase();
const failed = isError || providerStatus === 'failed' || resp.ok === false;

// A failed call is classified into one readable sentence; a provider that answers
// ok:false (no exception) keeps its own message verbatim.
const classified = isError ? classifyProviderError(incoming.error) : null;
const errorDetail = isError
  ? classified.detail
  : (failed ? String(resp.error_message || resp.error || resp.detail || 'Provider reported a failure').slice(0, 300) : '');

const payload = {
  provider: 'meta_whatsapp',
  channel: 'whatsapp',
  direction: 'outbound',
  status: failed ? 'failed' : 'sent',
  patient_name: base.patient_name || '',
  patient_phone: base.patient_phone || '',
