const payload = {
  provider: 'voicebip',
  channel: 'voice',
  direction: 'outbound',
  status: 'failed',
  patient_name: voiceItem.patient_name || '',
  patient_phone: voiceItem.patient_phone || '',
  request_code: requestCode,
  external_ref: 'probe-' + requestCode,
  summary: 'Voice nudge suppressed: patient status could not be verified.',
  error_detail: 'Status probe failed - voice call suppressed (fail closed): ' + message,
};

